'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const s = input[0] || '';

const vis = Array.from({ length: 110 }, () => Array(110).fill(1));
const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

function bfs(l, u, xi, yi) {
    const queue = [[l, u, 0]];
    let head = 0;
    vis[l][u] = 1;

    while (head < queue.length) {
        const [x, y, step] = queue[head++];

        if (x === xi && y === yi) return step;

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx < 0 || ny < 0) continue;
            if (vis[nx][ny]) continue;

            vis[nx][ny] = 1;
            queue.push([nx, ny, step + 1]);
        }
    }
}

let x = 0;
let y = 0;
let xx = 0;
let yy = 0;

for (const ch of s) {
    if (ch === 'L') y--;
    if (ch === 'R') y++;
    if (ch === 'U') x--;
    if (ch === 'D') x++;

    xx = Math.min(xx, x);
    yy = Math.min(yy, y);
}

xx = -xx;
yy = -yy;
x = xx;
y = yy;

for (const ch of s) {
    if (ch === 'L') y--;
    if (ch === 'R') y++;
    if (ch === 'U') x--;
    if (ch === 'D') x++;

    vis[x][y] = 0;
}

const ans = bfs(xx, yy, x, y);
console.log(ans === s.length ? 'OK' : 'BUG');

